func zzTmpExpected(fullPath, reqPath string) Params {
	if fullPath == "" {
		return nil
	}
	if !strings.ContainsAny(fullPath, ":*") {
		return nil
	}
	var out Params
	fp := fullPath
	rp := reqPath
	for len(fp) > 0 {
		// find next wildcard
		ci := strings.IndexAny(fp, ":*")
		if ci < 0 {
			return out
		}
		// static prefix must match
		if !strings.HasPrefix(rp, fp[:ci]) {
			return nil
		}
		rp = rp[ci:]
		fp = fp[ci:]
		if fp[0] == ':' {
			// find end of name
			end := strings.IndexByte(fp, '/')
			var name string
			if end < 0 {
				name = fp[1:]
				fp = ""
			} else {
				name = fp[1:end]
				fp = fp[end:]
			}
			// value is up to next '/'
			ve := strings.IndexByte(rp, '/')
			var val string
			if ve < 0 {
				val = rp
				rp = ""
			} else {
				val = rp[:ve]
				rp = rp[ve:]
			}
			out = append(out, Param{Key: name, Value: val})
		} else {
			name := fp[1:]
			fp = ""
			out = append(out, Param{Key: name, Value: rp})
			rp = ""
		}
	}
	if rp != "" {
		return nil
	}
	return out
}

func zzTmpInstantiate(route string, rnd *rand.Rand) string {
	tokens := []string{"a", "ab", "abc", "new", "gin", "test", "whoami", "root", "x", "1", "123abc", "public", "secondthing", "golang", "e", "e1", "cc", "dd"}
	var b strings.Builder
	i := 0
	for i < len(route) {
		c := route[i]
		if c == ':' {
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			b.WriteString(tokens[rnd.Intn(len(tokens))])
			i = j
